using System.Security.Claims;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Server;
using sv_4eae4eab306e4d4a976d5a93958eda71.Auth;
using sv_4eae4eab306e4d4a976d5a93958eda71.Client.Pages;
using sv_4eae4eab306e4d4a976d5a93958eda71.Components;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents()
    .AddInteractiveWebAssemblyComponents();

builder.Services.AddAuthorization();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddScoped<AuthenticationStateProvider, PersistingAuthenticationStateProvider>();

var app = builder.Build();

// Seed the hardcoded user on every request via middleware
app.Use(async (context, next) =>
{
    var authStateProvider = context.RequestServices.GetRequiredService<AuthenticationStateProvider>()
        as ServerAuthenticationStateProvider;

    if (authStateProvider is not null)
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, "bob@example.com"),
            new(ClaimTypes.Email, "bob@example.com"),
            new(ClaimTypes.Role, "User"),
            new(ClaimTypes.Role, "Editor"),
        };
        var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
        authStateProvider.SetAuthenticationState(
            Task.FromResult(new AuthenticationState(new ClaimsPrincipal(identity))));
    }

    await next();
});

